/bin/bash -lc "node --input-type=module <<'NODE'
import { readFileSync, writeFileSync } from 'node:fs';

const manifest = JSON.parse(readFileSync('work/lib/package.json', 'utf8'));
const { readMinor, mulDivMinor } = await import(new URL(manifest.exports, new URL('./work/lib/', import.meta.url)));
const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const settlement = rows.map(({ id, unitMinor, quantity }) => {
  if ("'!Number.isSafeInteger(quantity)) {
    throw new Error(`Invalid quantity for ${id}`);
  }
  // Division by 1 gives an exact product in either supported rounding mode.
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, '"'floor');
  return {
    id,
    net: { unit: 'EUR-cent', value: net.toString() },
    fee: {
      status: 'blocked',
      requiredDecision: 'Марине, владельцу расчётов, нужно утвердить числитель и знаменатель ставки сбора и правило округления для этой операции.',
      source: 'R-35 (work/owner.md)',
    },
  };
});
writeFileSync('settlement.json', JSON.stringify(settlement, null, 2) + '\\n', { flag: 'wx' });
NODE"

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { readMinor } from './work/lib/money.mjs';

const rows = JSON.parse(readFileSync('work/rows.json', 'utf8'));
const settlement = JSON.parse(readFileSync('settlement.json', 'utf8'));
const expected = new Map([['BR', 153n], ['BS', -30n]]);
assert.deepEqual(settlement.map(({ id }) => id), rows.map(({ id }) => id));
for (const { id, net, fee } of settlement) {
  assert.deepEqual(net, { unit: 'EUR-cent', value: expected.get(id).toString() });
  assert.equal(readMinor(net.value), expected.get(id));
  assert.deepEqual(Object.keys(fee).sort(), ['requiredDecision', 'source', 'status']);
  assert.equal(fee.status, 'blocked');
  assert.match(fee.requiredDecision, /Марине.*числитель и знаменатель.*правило округления/);
  assert.match(fee.source, /"'^R-35/);
}
console.log('"'Verified both settlement rows, exact DTOs and blocked fees.');
NODE"

